// Valid fulfillment inventory allocation resolver
export async function resolveAllocateInventory(input: { orderId: string; items: Array<{ sku: string; quantity: number }> }) {
  const [job] = await db.insert(schema.fulfillmentJobs).values({
    orderId: input.orderId,
    status: 'QUEUED',
